<?php $v=static fn($k)=>htmlspecialchars((string)($project[$k]??''),ENT_QUOTES,'UTF-8');ob_start();?><div class="d-flex justify-content-between mb-4"><h1 class="h2"><?=empty($project['id'])?'Novo projeto':'Editar projeto'?></h1><a href="<?=htmlspecialchars(base_url('admin'))?>" class="btn btn-outline-light">Voltar</a></div><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><form class="card p-4" action="<?=htmlspecialchars(base_url('admin/projeto/salvar'))?>" method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(\App\Core\Csrf::token())?>"><input type="hidden" name="id" value="<?=$v('id')?>"><div class="row g-3"><div class="col-md-8"><label class="form-label">Título *</label><input name="title" class="form-control" maxlength="120" required value="<?=$v('title')?>"></div><div class="col-md-4"><label class="form-label">Categoria *</label><select name="category" class="form-select" required><?php foreach(['sites'=>'Sites','landing-pages'=>'Landing pages','lojas'=>'Lojas virtuais','catalogos'=>'Catálogos','pagina-links'=>'Páginas de links'] as $key=>$label):?><option value="<?=$key?>" <?=($project['category']??'')===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Descrição *</label><textarea name="description" rows="4" maxlength="2000" class="form-control" required><?=$v('description')?></textarea></div><div class="col-md-6"><label class="form-label">Tipo de projeto</label><input name="type" class="form-control" value="<?=$v('type')?>"></div><div class="col-md-6"><label class="form-label">Tecnologias (separadas por vírgula)</label><input name="technologies" class="form-control" value="<?=htmlspecialchars(implode(', ',is_array($project['technologies']??null)?$project['technologies']:explode(',',(string)($project['technologies']??''))))?>"></div><div class="col-md-6"><label class="form-label">Link externo (https://)</label><input name="link" type="url" class="form-control" value="<?=$v('link')?>"></div><div class="col-md-3"><label class="form-label">Ordem</label><input name="order" type="number" min="0" class="form-control" value="<?=htmlspecialchars((string)($project['order']??999))?>"></div><div class="col-md-3 d-flex align-items-end"><div class="form-check mb-2"><input name="published" value="1" type="checkbox" class="form-check-input" id="published" <?=!empty($project['published'])?'checked':''?>><label for="published" class="form-check-label">Publicado</label></div></div><div class="col-12"><label class="form-label">Imagem (JPG, PNG ou WebP, até 3 MB)</label><input type="file" name="image_upload" accept="image/jpeg,image/png,image/webp" class="form-control"><?php if(!empty($project['image'])):?><small class="text-white-50">Imagem atual: <?=htmlspecialchars((string)$project['image'])?></small><?php endif;?></div></div><button class="btn btn-info mt-4">Salvar projeto</button></form><?php $content=ob_get_clean();$title='Editar projeto';require __DIR__.'/layout.php';